export type OnboardingCopyKey = keyof typeof ONBOARDING_COPY;
export function onboardingText(language: string, key: OnboardingCopyKey, values: Record<string, string | number> = {}): string {
  if (key === 'stage_flow' || key === 'stage_bump' || key === 'stage_mommy') return lifeStageName(key.slice(6) as 'flow' | 'bump' | 'mommy', language);
  const index = ONBOARDING_LANGUAGES.indexOf(language as typeof ONBOARDING_LANGUAGES[number]);
  const copy = getCachedTranslation(`onboarding.${key}`, language) ?? ONBOARDING_COPY[key]?.[index < 0 ? 0 : index];
  if (!copy) throw new Error(`ONBOARDING_TRANSLATION_MISSING:${key}`);
  return copy.replace(/\{(\w+)\}/g, (match, field) => values[field] === undefined ? match : String(values[field]));
}
export function onboardingLocale(language: string): string {
  return appLanguageLocale(language);
}
export function onboardingNumber(language: string, value: number): string {
  return new Intl.NumberFormat(onboardingLocale(language), { maximumFractionDigits: 2 }).format(value);
}
export function onboardingDate(language: string, value: string): string {
  return new Intl.DateTimeFormat(onboardingLocale(language), { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: 'UTC' }).format(new Date(`${value}T12:00:00Z`));
}
